Data.DatabaseSchemes:
CREATE TABLE IF NOT EXISTS raw_telemetry (
    id UUID PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    source_system VARCHAR(255) NOT NULL,
    metric_name VARCHAR(255),
    log_message TEXT,
    event_type VARCHAR(100),
    payload JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_raw_telemetry_timestamp ON raw_telemetry (timestamp);
CREATE INDEX IF NOT EXISTS idx_raw_telemetry_source_system ON raw_telemetry (source_system);

CREATE TABLE IF NOT EXISTS processed_features (
    id UUID PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    entity_id VARCHAR(255) NOT NULL, -- e.g., server_id, app_instance_id
    entity_type VARCHAR(100) NOT NULL, -- e.g., server, application
    feature_vector JSONB,
    processed_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_processed_features_timestamp ON processed_features (timestamp);
CREATE INDEX IF NOT EXISTS idx_processed_features_entity ON processed_features (entity_id, entity_type);

CREATE TABLE IF NOT EXISTS incident_predictions (
    id UUID PRIMARY KEY,
    prediction_timestamp TIMESTAMPTZ NOT NULL,
    entity_id VARCHAR(255) NOT NULL,
    entity_type VARCHAR(100) NOT NULL,
    prediction_score FLOAT NOT NULL,
    prediction_label VARCHAR(50),
    model_version VARCHAR(50),
    confidence_level FLOAT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_incident_predictions_timestamp ON incident_predictions (prediction_timestamp);
CREATE INDEX IF NOT EXISTS idx_incident_predictions_entity ON incident_predictions (entity_id, entity_type);

CREATE TABLE IF NOT EXISTS alerts (
    id UUID PRIMARY KEY,
    alert_timestamp TIMESTAMPTZ NOT NULL,
    prediction_id UUID REFERENCES incident_predictions(id),
    entity_id VARCHAR(255) NOT NULL,
    entity_type VARCHAR(100) NOT NULL,
    severity VARCHAR(50) NOT NULL,
    status VARCHAR(50) DEFAULT 'OPEN',
    description TEXT,
    triggered_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_alerts_timestamp ON alerts (alert_timestamp);
CREATE INDEX IF NOT EXISTS idx_alerts_entity ON alerts (entity_id, entity_type);
CREATE INDEX IF NOT EXISTS idx_alerts_status ON alerts (status);

